function validate([img]) {
  if (!Array.isArray(img) || img.length < 1 || img.length > 200) return 'img needs 1 to 200 rows.';
  const n = img[0].length;
  if (n < 1 || n > 200) return 'Each row needs 1 to 200 values.';
  for (const row of img) {
    if (row.length !== n) return 'All rows must have the same length.';
    if (row.some(v => !Number.isInteger(v) || v < 0 || v > 255)) return 'Each pixel is an integer from 0 to 255.';
  }
  return null;
}

