function imageSmoother(img) {
  // 2D prefix sums: pre[i][j] is the total of img[0..i-1][0..j-1].
  const m = img.length, n = img[0].length;
  const pre = Array.from({ length: m + 1 }, () => new Array(n + 1).fill(0));
  for (let i = 0; i < m; i++)
    for (let j = 0; j < n; j++)
      pre[i + 1][j + 1] = img[i][j] + pre[i][j + 1] + pre[i + 1][j] - pre[i][j];
  const out = [];
  for (let i = 0; i < m; i++) {
    const line = [];
    for (let j = 0; j < n; j++) {
      const top = Math.max(0, i - 1), bottom = Math.min(m - 1, i + 1);
      const leftCol = Math.max(0, j - 1), rightCol = Math.min(n - 1, j + 1);
      const total = pre[bottom + 1][rightCol + 1] - pre[top][rightCol + 1] - pre[bottom + 1][leftCol] + pre[top][leftCol];
      const cells = (bottom - top + 1) * (rightCol - leftCol + 1);
      line.push((total - total % cells) / cells);
    }
    out.push(line);
  }
  return out;
}

