function generate(rand, size) {
  const m = size === 'large' ? 60 + Math.floor(rand() * 41) : 1 + Math.floor(rand() * 5);
  const n = size === 'large' ? 60 + Math.floor(rand() * 41) : 1 + Math.floor(rand() * 5);
  const style = Math.floor(rand() * 3);
  const cell = () => {
    if (style === 0) return Math.floor(rand() * 256);
    if (style === 1) return rand() < 0.5 ? 0 : 255;
    return Math.floor(rand() * 4);
  };
  return [Array.from({ length: m }, () => Array.from({ length: n }, cell))];
}
